#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    unordered_map<long long, int> count;
    for (int i = 0; i < n; i++) count[a[i]]++;
    bool found = false;
    long long answer = 0;
    for (int i = 0; i < n; i++) {
        if (count[a[i]] == 1) {
            found = true;
            answer = a[i];
            break;
        }
    }
    if (found) cout << answer << "\n";
    else cout << "none\n";

    return 0;
}

